import hashlib, json
from pathlib import Path

roots = [Path('products/distribution/sqlite-community-directory'), Path('products/services/sqlite-repair/bespoke-inbound'), Path('products/services/sqlite-repair/original-fixture/verified-handoff')]
names = {'operator-referral-packet.md', 'operator-fixed-scope-quote-controls.json', 'operator-fixed-scope-quote-en-fr.md', 'director-referral-candidate.diff', 'director-referral-candidate.json', 'manifest.json'}
for root in roots:
    for path in sorted(root.rglob('*')):
        if not path.is_file():
            continue
        if path.name not in names and not (root == roots[2] and path.suffix == '.json'):
            continue
        raw = path.read_bytes()
        print(json.dumps({'path': str(path), 'sha256': hashlib.sha256(raw).hexdigest(), 'bytes': len(raw)}))
        if path.name in {'operator-fixed-scope-quote-controls.json', 'director-referral-candidate.json', 'manifest.json'}:
            print(raw.decode('utf-8'))
        elif root == roots[2] and path.suffix == '.json':
            report = json.loads(raw)
            if isinstance(report, dict):
                print(json.dumps({k: v for k, v in report.items() if k not in {'seed_sql', 'query_sql'}}))
